import{_ as i,l as n,o as e,c as l,v as t,p as s,x as o,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"率失真","description":"","frontmatter":{"title":"率失真","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rate-distortion.md","filePath":"cs/rate-distortion.md","lastUpdated":1789023840000}'),D={name:"cs/rate-distortion.md"};function c(m,a,_,u,E,x){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="率失真" tabindex="-1">率失真 <a class="header-anchor" href="#率失真" aria-label="Permalink to &quot;率失真&quot;">​</a></h1><div class="epigraph"><p>允许平均失真 $\\le D$ 时，每符号最少仍要约 $R(D)=\\min I(X;\\hat X)$ 比特；$D=0$ 退回熵，JPEG 一类有损从这里量。</p><footer>—— 据 Shannon, 1959；Cover and Thomas 整理</footer></div><p><a href="/cs/ldpc-turbo">上一课</a>把逼近容量的码钉到直觉。无损路径从信源定理到 LZ、信道从容量到 LDPC。缺口是<strong>有损</strong>：像素不必精确复原。率失真函数 \\(R(D)\\)。本课钉定义与高斯例子，不写编解码器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>失真 \\(d(x,\\hat x)\\)（平方、汉明）。\\(R(D)=\\min_{p(\\hat x|x):\\ \\mathbb{E}d\\le D}I(X;\\hat X)\\)。\\(D=0\\) 且 \\(d\\) 为汉明时 \\(R(0)=H(X)\\)。高斯、平方失真：\\(R(D)=\\frac12\\log(\\sigma^2/D)\\)（\\(D\\le\\sigma^2\\)）。反向：给速率 \\(R\\) 能达到的最小失真。存在性仍随机码；JPEG 量化是启发式逼近，不是 \\(R(D)\\) 的证明。</p><p>与容量：信道是固定 \\(p(y|x)\\) 选 \\(p(x)\\)；率失真是固定 \\(p(x)\\) 选「试验信道」\\(p(\\hat x|x)\\)。对偶。</p><h3 id="失真不是「看起来差不多」" tabindex="-1">失真不是「看起来差不多」 <a class="header-anchor" href="#失真不是「看起来差不多」" aria-label="Permalink to &quot;失真不是「看起来差不多」&quot;">​</a></h3><p>必须先约定 \\(d\\)。感知上好的图可能平方误差大。本课不进视觉模型。</p><p><span class="marginnote">Shannon 1959 率失真。Cover–Thomas 第 10 章。Berger 的书。本课不证着色、高分辨近似全文。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画 \\(R(D)\\) 下降曲线。指出：量化器 + 熵编码是实践上界，未必等于 \\(R(D)\\)。向量量化以块逼近。不要把压缩比写成 \\(R(D)\\)——缺 \\(D\\) 的数。</p>',11)),(e(),s(h,null,{default:o(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E4%BF%A1%E6%BA%90%20X%22%5D%20--%3E%20D%5B%22%E5%85%81%E8%AE%B8%E5%A4%B1%E7%9C%9F%20D%22%5D%0A%20%20D%20--%3E%20RD%5B%22R(D)%3Dmin%20I(X%3BX%CC%82)%22%5D%0A%20%20RD%20--%3E%20LOSSY%5B%22%E6%9C%89%E6%8D%9F%E7%A0%81%E9%80%9F%E7%8E%87%E4%B8%8B%E7%95%8C%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信息单元的无损/有噪/有损三块至此齐：下界分别是 \\(H\\)、\\(C\\)、\\(R(D)\\)。下一课 KL 把「用错模型」的额外比特钉成相对熵，给交叉熵与最大熵铺路。</p><p>\\(R(D)\\) 不可计算一般形式；构造性仍难。本课当尺子。</p><p>反向水灌：高斯独立分量把速率分给方差大的轴。高分辨量化：\\(R(D)\\approx h(X)-\\log D+\\) 常数。实践：变换 + 量化 + 熵编码给出 \\(R(D)\\) 的上界。没有 \\(d(\\cdot,\\cdot)\\) 的数，谈不上「压了多少信息」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 JPEG 标记，不引入感知编码标准。不把大模型的重建损失当 \\(R(D)\\)。后课默认：有损的信息下界是 \\(R(D)\\)。下一课 KL 与交叉熵。</p><p>\\(D=0\\) 回到无损 \\(H\\)；允许失真后 \\(R(D)\\) 下降。没有事先约定的 \\(d\\)，有损比没有信息论意义。实践编解码是上界，高斯平方给出少数闭式。</p><p>上一课留下的缺口在本课收口；「率失真」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(R(D)\\) 是失真 \\(D\\) 下的最小互信息速率。</li><li>\\(D=0\\) 回到无损熵；高斯平方有闭式。</li><li>实践编解码给出上界，不是定义。</li><li>出处：Shannon, 1959；Cover and Thomas。</li></ul>',10))])}const b=i(D,[["render",c]]);export{f as __pageData,b as default};
